input.sparql:
PREFIX brick: <http://brickcv.org/ontology#>
PREFIX ref: <https://brickschema.org/schema/1.2/bricks#>
SELECT ?ts ?point ?point_uri ?class WHERE {
  ?zone brick:hasSubgraph* ?z.
  FILTER(str(?z) = "Perimeter_mid_ZN_3")
}

SELECT ?s ?p ?o WHERE {
  ?s ?p ?o .
  FILTER(regex(str(?s), "ZN_3") || regex(str(?p), "Perimeter") || regex(str(?o), "Perimeter"))
} LIMIT 50

SELECT ?cls (COUNT(?s) AS ?n) WHERE {
  ?s a ?cls .
} GROUP BY ?cls

SELECT ?zone ?lbl ?sensor ?class ?tsid WHERE {
  ?zone a brick:HVAC_Zone .
  ?zone rdfs:label ?lbl .
  FILTER(regex(?lbl, "Perimeter_mid_ZN_3"))
  ?sensor brick:hasLocation ?zone .
  ?sensor a ?class .
  OPTIONAL { ?sensor ref:hasTimeseriesId ?tsid }
} LIMIT 50

SELECT ?s ?prop ?o WHERE {
  ?z a brick:HVAC_Zone .
  ?z rdfs:label ?lbl .
  FILTER(?lbl = "Perimeter_mid_ZN_3")
  ?s ?prop ?z .
} LIMIT 100

